// Normaliza a entrada enviada pelo script Python
const input = $input.first().json;
let lista = [];

if (Array.isArray(input.body)) {
  lista = input.body;
} else if (input.body && Array.isArray(input.body.clientes)) {
  lista = input.body.clientes;
} else if (Array.isArray(input.clientes)) {
  lista = input.clientes;
} else if (input.body && typeof input.body === 'object') {
  lista = [input.body];
} else {
  lista = [input];
}

return lista.map(c => {
  const perfilRaw = (c.perfil || c.Perfil || c.profile || '').toString().trim();
  return {
    json: {
      nome: c.nome || c.Nome || c.name || 'Cliente',
      email: c.email || c.Email || '',
      saldo: c.saldo || c.Saldo || '0,00',
      perfil: perfilRaw,
      perfil_chave: perfilRaw.toLowerCase()
    }
  };
});

// Padroniza as colunas do CSV para o cruzamento (Merge)
return $input.all().map(item => {
  const row = item.json;
  const keys = Object.keys(row);

  const perfilKey = keys.find(k => k.toLowerCase().includes('perfil') || k.toLowerCase().includes('profile')) || keys[0];
  const prodKey = keys.find(k => k !== perfilKey) || keys[1];

  const perfilVal = (row[perfilKey] || '').toString().trim();

  return {
    json: {
      ...row,
      perfil_csv: perfilVal,
      perfil_chave: perfilVal.toLowerCase(),
      recomendacao_csv: row[prodKey] || ''
    }
  };
});

return $input.all().map(item => {
  const d = item.json;
  const nome = d.nome || 'Cliente';
  const saldo = d.saldo || '0,00';
  const perfil = d.perfil || 'Investidor';
  const produto = d.recomendacao_csv || d.produto || d.investimento || d.opcoes || 'Carteira Recomendada';

  let mensagem = '';
  const pLower = perfil.toLowerCase();

  if (pLower.includes('conservador')) {
    mensagem = `Olá, ${nome}! Analisamos o seu perfil Conservador e seu saldo disponível de R$ ${saldo}. Para garantir a máxima segurança e liquidez do seu patrimônio, nossa recomendação de renda fixa é: ${produto}.`;
  } else if (pLower.includes('moderado')) {
    mensagem = `Olá, ${nome}! Com base no seu perfil Moderado e saldo de R$ ${saldo}, o ideal é buscar um equilíbrio estratégico entre segurança e rentabilidade. Recomendamos para você: ${produto}.`;
  } else if (pLower.includes('arrojado') || pLower.includes('agressivo')) {
    mensagem = `Olá, ${nome}! Vimos que seu perfil é Arrojado e você conta com R$ ${saldo} disponíveis. Para potencializar seus ganhos no longo prazo com maior foco em retorno, destacamos: ${produto}.`;
  } else {
    mensagem = `Olá, ${nome}! Para o seu perfil (${perfil}) e saldo de R$ ${saldo}, nossa recomendação personalizada de investimento é: ${produto}.`;
  }

  return {
    json: {
      nome,
      email: d.email,
      perfil,
      saldo,
      produto_recomendado: produto,
      mensagem_personalizada: mensagem
    }
  };
});
